import { querySnowflake } from "@/lib/snowflake"
import { DB_SCHEMA, DAMAGE_RATE } from "@/lib/constants"
export const dynamic = "force-dynamic"

export async function POST(req: Request) {
  try {
    const body = await req.json()
    const { sessionId, playerName, questionNo, questionId, answerPct, correctPct, remainingHpBefore } = body

    const errorAbs = Math.round(Math.abs(answerPct - correctPct) * 10) / 10
    const damage = Math.round(errorAbs * DAMAGE_RATE)
    const remainingHp = Math.max(0, remainingHpBefore - damage)

    await querySnowflake(
      `INSERT INTO ${DB_SCHEMA}.game_answer
       (SESSION_ID, PLAYER_NAME, QUESTION_NO, QUESTION_ID, ANSWER_PCT, ERROR_ABS, DAMAGE, REMAINING_HP)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      { binds: [sessionId, playerName, questionNo, questionId, answerPct, errorAbs, damage, remainingHp] }
    )

    return Response.json({ errorAbs, damage, remainingHp })
  } catch (e) {
    console.error("Failed to record answer", e)
    return Response.json({ error: "Failed to record answer" }, { status: 500 })
  }
}

import { querySnowflake } from "@/lib/snowflake"
import { DB_SCHEMA } from "@/lib/constants"
export const dynamic = "force-dynamic"

export async function GET() {
  try {
    const rows = await querySnowflake(
      `SELECT PLAYER_NAME, MODE, SCORE, QUESTIONS_CLEARED, CREATED_AT
       FROM ${DB_SCHEMA}.leaderboard
       ORDER BY SCORE DESC, CREATED_AT ASC
       LIMIT 20`
    )
    const entries = (rows as Record<string, unknown>[]).map((r) => ({
      playerName: String(r.PLAYER_NAME),
      mode: String(r.MODE),
      score: Number(r.SCORE),
      questionsCleared: Number(r.QUESTIONS_CLEARED),
      createdAt: r.CREATED_AT instanceof Date ? r.CREATED_AT.toISOString() : String(r.CREATED_AT),
    }))
    return Response.json(entries)
  } catch (e) {
    console.error("Failed to fetch leaderboard", e)
    return Response.json({ error: "Failed to fetch leaderboard" }, { status: 500 })
  }
}

export async function POST(req: Request) {
  try {
    const body = await req.json()
    const { playerName, mode, score, questionsCleared } = body
    await querySnowflake(
      `INSERT INTO ${DB_SCHEMA}.leaderboard (PLAYER_NAME, MODE, SCORE, QUESTIONS_CLEARED)
       VALUES (?, ?, ?, ?)`,
      { binds: [playerName, mode, score, questionsCleared] }
    )
    return Response.json({ success: true })
  } catch (e) {
    console.error("Failed to save score", e)
    return Response.json({ error: "Failed to save score" }, { status: 500 })
  }
}

import { querySnowflake } from "@/lib/snowflake"
import { DB_SCHEMA } from "@/lib/constants"
export const dynamic = "force-dynamic"

export async function GET(req: Request) {
  const url = new URL(req.url)
  const count = Number(url.searchParams.get("count") || "5")
  try {
    const rows = await querySnowflake(
      `SELECT QUESTION_ID, QUESTION_TYPE, QUESTION_TEXT, ANSWER_PCT
       FROM ${DB_SCHEMA}.question_pool
       ORDER BY RANDOM()
       LIMIT ${count}`
    )
    const questions = (rows as Record<string, unknown>[]).map((r) => ({
      questionId: Number(r.QUESTION_ID),
      questionType: String(r.QUESTION_TYPE),
      questionText: String(r.QUESTION_TEXT),
      answerPct: Number(r.ANSWER_PCT),
    }))
    return Response.json(questions)
  } catch (e) {
    console.error("Failed to fetch questions", e)
    return Response.json(
      { error: e instanceof Error ? e.message : "Failed to fetch questions" },
      { status: 500 }
    )
  }
}

import { querySnowflake } from "@/lib/snowflake"
import { DB_SCHEMA } from "@/lib/constants"
export const dynamic = "force-dynamic"

export async function POST(req: Request) {
  try {
    const body = await req.json()
    const { mode, playerName } = body

    const sessionId = crypto.randomUUID()
    const roomCode = String(Math.floor(Math.random() * 10000)).padStart(4, "0")

    const qRows = await querySnowflake(
      `SELECT QUESTION_ID FROM ${DB_SCHEMA}.question_pool ORDER BY RANDOM() LIMIT 5`
    )
    const questionIds = (qRows as Record<string, unknown>[]).map((r) => String(r.QUESTION_ID)).join(",")

    await querySnowflake(
      `INSERT INTO ${DB_SCHEMA}.game_session (SESSION_ID, ROOM_CODE, MODE, STATUS, PLAYER1_NAME, QUESTION_IDS)
       VALUES (?, ?, ?, 'WAITING', ?, ?)`,
      { binds: [sessionId, roomCode, mode, playerName, questionIds] }
    )

    return Response.json({ sessionId, roomCode, questionIds: questionIds.split(",").map(Number) })
  } catch (e) {
    console.error("Failed to create session", e)
    return Response.json({ error: "Failed to create session" }, { status: 500 })
  }
}

export async function GET(req: Request) {
  const url = new URL(req.url)
  const roomCode = url.searchParams.get("roomCode")
  const sessionId = url.searchParams.get("sessionId")

  try {
    let rows: Record<string, unknown>[]
    if (sessionId) {
      rows = await querySnowflake(
        `SELECT * FROM ${DB_SCHEMA}.game_session WHERE SESSION_ID = ?`,
        { binds: [sessionId] }
      ) as Record<string, unknown>[]
    } else if (roomCode) {
      rows = await querySnowflake(
        `SELECT * FROM ${DB_SCHEMA}.game_session WHERE ROOM_CODE = ? AND STATUS != 'FINISHED'
         AND CREATED_AT > DATEADD(MINUTE, -10, CURRENT_TIMESTAMP())
         ORDER BY CREATED_AT DESC LIMIT 1`,
        { binds: [roomCode] }
      ) as Record<string, unknown>[]
    } else {
      return Response.json({ error: "roomCode or sessionId required" }, { status: 400 })
    }

    if (!rows || rows.length === 0) {
      return Response.json({ error: "Session not found" }, { status: 404 })
    }

    const s = rows[0]
    const qidsStr = String(s.QUESTION_IDS || "")
    const questionIds = qidsStr ? qidsStr.split(",").map(Number) : []

    // Get questions data
    let questions: Record<string, unknown>[] = []
    if (questionIds.length > 0) {
      questions = await querySnowflake(
        `SELECT QUESTION_ID, QUESTION_TYPE, QUESTION_TEXT, ANSWER_PCT
         FROM ${DB_SCHEMA}.question_pool
         WHERE QUESTION_ID IN (${questionIds.join(",")})`
      ) as Record<string, unknown>[]
    }

    // Get answers
    const answers = await querySnowflake(
      `SELECT * FROM ${DB_SCHEMA}.game_answer WHERE SESSION_ID = ? ORDER BY QUESTION_NO, CREATED_AT`,
      { binds: [String(s.SESSION_ID)] }
    ) as Record<string, unknown>[]

    return Response.json({
      sessionId: String(s.SESSION_ID),
      roomCode: String(s.ROOM_CODE),
      status: String(s.STATUS),
      mode: String(s.MODE),
      player1Name: String(s.PLAYER1_NAME),
      player2Name: s.PLAYER2_NAME ? String(s.PLAYER2_NAME) : null,
      questionIds,
      questions: questions.map((q) => ({
        questionId: Number(q.QUESTION_ID),
        questionType: String(q.QUESTION_TYPE),
        questionText: String(q.QUESTION_TEXT),
        answerPct: Number(q.ANSWER_PCT),
      })),
      answers: answers.map((a) => ({
        playerName: String(a.PLAYER_NAME),
        questionNo: Number(a.QUESTION_NO),
        answerPct: Number(a.ANSWER_PCT),
        errorAbs: Number(a.ERROR_ABS),
        damage: Number(a.DAMAGE),
        remainingHp: Number(a.REMAINING_HP),
      })),
    })
  } catch (e) {
    console.error("Failed to get session", e)
    return Response.json({ error: "Failed to get session" }, { status: 500 })
  }
}

export async function PUT(req: Request) {
  try {
    const body = await req.json()
    const { sessionId, playerName, status } = body

    if (playerName) {
      await querySnowflake(
        `UPDATE ${DB_SCHEMA}.game_session SET PLAYER2_NAME = ?, STATUS = 'PLAYING', UPDATED_AT = CURRENT_TIMESTAMP()
         WHERE SESSION_ID = ? AND PLAYER2_NAME IS NULL`,
        { binds: [playerName, sessionId] }
      )
    }
    if (status) {
      await querySnowflake(
        `UPDATE ${DB_SCHEMA}.game_session SET STATUS = ?, UPDATED_AT = CURRENT_TIMESTAMP()
         WHERE SESSION_ID = ?`,
        { binds: [status, sessionId] }
      )
    }

    return Response.json({ success: true })
  } catch (e) {
    console.error("Failed to update session", e)
    return Response.json({ error: "Failed to update session" }, { status: 500 })
  }
}

"use client"

import { useState, useCallback } from "react"
import type { Question, GameMode, GamePhase, PlayerState, PlayerAnswer } from "@/lib/game-types"
import { DAMAGE_RATE, INITIAL_HP, TOTAL_QUESTIONS } from "@/lib/constants"
import { TopScreen } from "@/components/game/top-screen"
import { SetupScreen } from "@/components/game/setup-screen"
import { QuestionScreen } from "@/components/game/question-screen"
import { SwapScreen } from "@/components/game/swap-screen"
import { ResultScreen } from "@/components/game/result-screen"
import { FinishedScreen } from "@/components/game/finished-screen"
import { OnlineWaitingScreen } from "@/components/game/online-waiting-screen"
import { OnlineGameScreen } from "@/components/game/online-game-screen"

function calcDamage(guess: number, correct: number): { errorAbs: number; damage: number } {
  const errorAbs = Math.round(Math.abs(guess - correct) * 10) / 10
  const damage = Math.round(errorAbs * DAMAGE_RATE)
  return { errorAbs, damage }
}

export function GameContainer() {
  const [phase, setPhase] = useState<GamePhase>("top")
  const [mode, setMode] = useState<GameMode>("solo")
  const [questions, setQuestions] = useState<Question[]>([])
  const [currentQ, setCurrentQ] = useState(0)
  const [player1, setPlayer1] = useState<PlayerState>({ name: "", hp: INITIAL_HP, answers: [], isGameOver: false })
  const [player2, setPlayer2] = useState<PlayerState>({ name: "", hp: INITIAL_HP, answers: [], isGameOver: false })
  const [currentPlayer, setCurrentPlayer] = useState(1)
  const [lastAnswer, setLastAnswer] = useState<{ p1?: PlayerAnswer; p2?: PlayerAnswer } | null>(null)
  const [onlineSessionId, setOnlineSessionId] = useState("")
  const [onlineRoomCode, setOnlineRoomCode] = useState("")

  const resetGame = useCallback(() => {
    setPhase("top")
    setQuestions([])
    setCurrentQ(0)
    setPlayer1({ name: "", hp: INITIAL_HP, answers: [], isGameOver: false })
    setPlayer2({ name: "", hp: INITIAL_HP, answers: [], isGameOver: false })
    setCurrentPlayer(1)
    setLastAnswer(null)
    setOnlineSessionId("")
    setOnlineRoomCode("")
  }, [])

  const startGame = useCallback(async (selectedMode: GameMode, p1Name: string, p2Name?: string) => {
    setMode(selectedMode)
    setPlayer1({ name: p1Name, hp: INITIAL_HP, answers: [], isGameOver: false })
    if (p2Name) {
      setPlayer2({ name: p2Name, hp: INITIAL_HP, answers: [], isGameOver: false })
    }

    if (selectedMode === "online") {
      setPhase("waiting")
      return
    }

    const res = await fetch("/api/questions?count=5")
    const qs = await res.json()
    setQuestions(qs)
    setCurrentQ(0)
    setCurrentPlayer(1)
    setPhase("playing")
  }, [])

  const submitAnswer = useCallback((guess: number) => {
    const q = questions[currentQ]
    const { errorAbs, damage } = calcDamage(guess, q.answerPct)

    if (mode === "solo") {
      const newHp = Math.max(0, player1.hp - damage)
      const answer: PlayerAnswer = {
        questionNo: currentQ + 1,
        questionId: q.questionId,
        answerPct: guess,
        correctPct: q.answerPct,
        errorAbs,
        damage,
        remainingHp: newHp,
      }
      const isOver = newHp <= 0
      setPlayer1((prev) => ({
        ...prev,
        hp: newHp,
        answers: [...prev.answers, answer],
        isGameOver: isOver,
      }))
      setLastAnswer({ p1: answer })
      setPhase("result")
    } else if (mode === "local") {
      if (currentPlayer === 1) {
        const newHp = Math.max(0, player1.hp - damage)
        const answer: PlayerAnswer = {
          questionNo: currentQ + 1,
          questionId: q.questionId,
          answerPct: guess,
          correctPct: q.answerPct,
          errorAbs,
          damage,
          remainingHp: newHp,
        }
        setPlayer1((prev) => ({
          ...prev,
          hp: newHp,
          answers: [...prev.answers, answer],
          isGameOver: newHp <= 0,
        }))
        setLastAnswer((prev) => ({ ...prev, p1: answer }))
        if (!player2.isGameOver) {
          setPhase("swap")
        } else {
          setPhase("result")
        }
      } else {
        const newHp = Math.max(0, player2.hp - damage)
        const answer: PlayerAnswer = {
          questionNo: currentQ + 1,
          questionId: q.questionId,
          answerPct: guess,
          correctPct: q.answerPct,
          errorAbs,
          damage,
          remainingHp: newHp,
        }
        setPlayer2((prev) => ({
          ...prev,
          hp: newHp,
          answers: [...prev.answers, answer],
          isGameOver: newHp <= 0,
        }))
        setLastAnswer((prev) => ({ ...prev, p2: answer }))
        setPhase("result")
      }
    }
  }, [questions, currentQ, mode, currentPlayer, player1.hp, player2.hp, player2.isGameOver])

  const nextQuestion = useCallback(() => {
    const nextQ = currentQ + 1

    if (mode === "solo") {
      if (player1.isGameOver || nextQ >= TOTAL_QUESTIONS) {
        setPhase("finished")
      } else {
        setCurrentQ(nextQ)
        setLastAnswer(null)
        setPhase("playing")
      }
    } else if (mode === "local") {
      const bothOver = player1.isGameOver && player2.isGameOver
      if (bothOver || nextQ >= TOTAL_QUESTIONS) {
        setPhase("finished")
      } else {
        setCurrentQ(nextQ)
        setCurrentPlayer(1)
        setLastAnswer(null)
        if (player1.isGameOver) {
          setCurrentPlayer(2)
        }
        setPhase("playing")
      }
    }
  }, [currentQ, mode, player1.isGameOver, player2.isGameOver])

  const handleSwapReady = useCallback(() => {
    setCurrentPlayer(2)
    setPhase("playing")
  }, [])

  const handleOnlineReady = useCallback((sessionId: string, roomCode: string, qs: Question[]) => {
    setOnlineSessionId(sessionId)
    setOnlineRoomCode(roomCode)
    setQuestions(qs)
    setPhase("playing")
  }, [])

  return (
    <div className="min-h-[calc(100vh-3.5rem)] flex flex-col items-center justify-center p-4">
      {phase === "top" && (
        <TopScreen onSelectMode={(m) => { setMode(m); setPhase("setup") }} />
      )}

      {phase === "setup" && (
        <SetupScreen mode={mode} onStart={startGame} onBack={resetGame} />
      )}

      {phase === "waiting" && mode === "online" && (
        <OnlineWaitingScreen
          playerName={player1.name}
          onReady={handleOnlineReady}
          onBack={resetGame}
        />
      )}

      {phase === "playing" && mode !== "online" && questions.length > 0 && (
        <QuestionScreen
          question={questions[currentQ]}
          questionNo={currentQ + 1}
          totalQuestions={TOTAL_QUESTIONS}
          playerName={mode === "local" ? (currentPlayer === 1 ? player1.name : player2.name) : player1.name}
          hp={currentPlayer === 1 ? player1.hp : player2.hp}
          isLocalMode={mode === "local"}
          onSubmit={submitAnswer}
        />
      )}

      {phase === "playing" && mode === "online" && (
        <OnlineGameScreen
          sessionId={onlineSessionId}
          playerName={player1.name}
          questions={questions}
          onFinished={(finalPlayer1, finalPlayer2) => {
            setPlayer1(finalPlayer1)
            setPlayer2(finalPlayer2)
            setPhase("finished")
          }}
        />
      )}

      {phase === "swap" && mode === "local" && (
        <SwapScreen nextPlayerName={player2.name} onReady={handleSwapReady} />
      )}

      {phase === "result" && (
        <ResultScreen
          mode={mode}
          lastAnswer={lastAnswer}
          player1Name={player1.name}
          player2Name={player2.name}
          player1GameOver={player1.isGameOver}
          player2GameOver={player2.isGameOver}
          questionNo={currentQ + 1}
          totalQuestions={TOTAL_QUESTIONS}
          onNext={nextQuestion}
        />
      )}

      {phase === "finished" && (
        <FinishedScreen
          mode={mode}
          player1={player1}
          player2={player2}
          onPlayAgain={() => { setPhase("setup") }}
          onBackToTop={resetGame}
        />
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import type { GameMode, PlayerState } from "@/lib/game-types"
import { TOTAL_QUESTIONS } from "@/lib/constants"

interface FinishedScreenProps {
  mode: GameMode
  player1: PlayerState
  player2: PlayerState
  onPlayAgain: () => void
  onBackToTop: () => void
}

function determineWinner(p1: PlayerState, p2: PlayerState): "p1" | "p2" | "draw" {
  const p1Cleared = p1.answers.length
  const p2Cleared = p2.answers.length
  const p1Finished = !p1.isGameOver || p1.answers.length >= TOTAL_QUESTIONS
  const p2Finished = !p2.isGameOver || p2.answers.length >= TOTAL_QUESTIONS

  if (p1Finished && !p2Finished) return "p1"
  if (!p1Finished && p2Finished) return "p2"
  if (p1Finished && p2Finished) {
    if (p1.hp > p2.hp) return "p1"
    if (p2.hp > p1.hp) return "p2"
    return "draw"
  }
  if (p1Cleared > p2Cleared) return "p1"
  if (p2Cleared > p1Cleared) return "p2"
  return "draw"
}

export function FinishedScreen({ mode, player1, player2, onPlayAgain, onBackToTop }: FinishedScreenProps) {
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)

  const isBattle = mode === "local" || mode === "online"
  const winner = isBattle ? determineWinner(player1, player2) : null

  const saveScore = async () => {
    setSaving(true)
    try {
      const entries = [{ playerName: player1.name, mode, score: player1.hp, questionsCleared: player1.answers.length }]
      if (isBattle && player2.name) {
        entries.push({ playerName: player2.name, mode, score: player2.hp, questionsCleared: player2.answers.length })
      }
      for (const entry of entries) {
        await fetch("/api/leaderboard", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(entry),
        })
      }
      setSaved(true)
    } catch {
      // ignore
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="w-full max-w-lg mx-auto flex flex-col items-center gap-6">
      <h2 className="text-3xl font-bold">ゲーム終了</h2>

      {isBattle && winner && (
        <div className="text-center">
          {winner === "draw" ? (
            <p className="text-2xl font-bold text-yellow-500">引き分け</p>
          ) : (
            <p className="text-2xl font-bold text-red-500">
              🎉 {winner === "p1" ? player1.name : player2.name} の勝ち！
            </p>
          )}
        </div>
      )}

      <div className={`w-full flex gap-4 ${!isBattle ? "justify-center" : ""}`}>
        <PlayerResult
          label={mode === "solo" ? "あなた" : player1.name}
          player={player1}
          isWinner={winner === "p1"}
        />
        {isBattle && player2.name && (
          <PlayerResult
            label={player2.name}
            player={player2}
            isWinner={winner === "p2"}
          />
        )}
      </div>

      {!saved && (
        <button
